import { CitationBlurb } from './CitationBlurb'
@Component
export struct ArticleTile {
 @Prop body: string = ''
 @Prop citation: string = ''
 build() {
  Column() {
   Text(this.body).fontSize(18)
   CitationBlurb({ text: this.citation })
  }
 }
}

